const megaSheetData = $('Leer Mega en Clientes TotalTv').first().json;
const chatwootMeta = $('Obtener Metadatos Chatwoot').first().json;

// 1. Verificar si la hoja MegaID ya existe en Chatwoot
const existingSheets = (chatwootMeta.sheets || []).map(s => s.properties && s.properties.title);
const sheetExists = existingSheets.includes('MegaID');

// 2. Obtener todas las suscripciones de Mega OTT API (paginadas)
const MEGA_API_KEY = '1655|Uk2GI2EUH0v8NIcUFjGwLeKLlp14bVmEi2rcGSuJ48ec8236';
let allSubs = [];
let page = 1;
let lastPage = 1;

while (page <= lastPage) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://megaott.net/api/v1/subscriptions?per_page=100&page=${page}`,
    headers: {
      'Authorization': `Bearer ${MEGA_API_KEY}`,
      'Accept': 'application/json',
      'User-Agent': 'Mozilla/5.0'
    },
    json: true
  });

  const subs = resp.data || [];
  allSubs = allSubs.concat(subs);
  lastPage = resp.last_page || resp.meta?.last_page || page;
  if (page >= lastPage || subs.length === 0) break;
  page++;
}

// 3. Crear índices de búsqueda rápida
const subById = new Map();
const subByUsername = new Map();
const subByNote = new Map();
const subByPhone = new Map();

for (const sub of allSubs) {
  if (sub.id) {
    subById.set(String(sub.id).trim(), sub);
  }
  if (sub.username) {
    subByUsername.set(String(sub.username).trim().toLowerCase(), sub);
  }
  if (sub.note) {
    const normNote = String(sub.note).toLowerCase().replace(/\s+/g, ' ').trim();
    if (normNote.length > 2) {
      subByNote.set(normNote, sub);
    }
  }
  if (sub.customer_phone || sub.whatsapp_telegram) {
    const rawPhone = sub.customer_phone || sub.whatsapp_telegram;
    const phoneDigits = String(rawPhone).replace(/\D/g, '');
    if (phoneDigits.length >= 7 && phoneDigits !== '13059861096' && phoneDigits !== '573009476271') {
      subByPhone.set(phoneDigits, sub);
    }
  }
}

// 4. Analizar cabeceras de la pestaña Mega
const rows = megaSheetData.values || [];
if (rows.length === 0) {
  return [{ json: { error: 'No data found in Mega sheet', sheetExists, rowsToWrite: [] } }];
}

const headers = rows[0].map(h => String(h || '').trim());
const colIdx = {
  nombre: headers.findIndex(h => /^nombre$/i.test(h) || /^name$/i.test(h)),
  apellido: headers.findIndex(h => /^apellido$/i.test(h) || /^last\s*name$/i.test(h)),
  usuario: headers.findIndex(h => /^usuario$/i.test(h) || /^user$/i.test(h) || /^username$/i.test(h)),
  clave: headers.findIndex(h => /^clave$/i.test(h) || /^password$/i.test(h) || /^pass$/i.test(h)),
  dns: headers.findIndex(h => /^dns$/i.test(h) && !/smarter/i.test(h)),
  dnsSmarters: headers.findIndex(h => /dns.*smarter|smarter.*dns/i.test(h)),
  telefono: headers.findIndex(h => /tel|cel|phone|movil/i.test(h))
};

// 5. Procesar cada fila de clientes
const outputRows = [
  ['Nombre', 'Apellido', 'Usuario', 'Clave', 'DNS', 'DNS Smarters', 'ID de mega']
];

let matchedCount = 0;
let unmatchedCount = 0;

for (let i = 1; i < rows.length; i++) {
  const row = rows[i];
  const nombre = colIdx.nombre !== -1 ? String(row[colIdx.nombre] || '').trim() : '';
  const apellido = colIdx.apellido !== -1 ? String(row[colIdx.apellido] || '').trim() : '';
  const usuario = colIdx.usuario !== -1 ? String(row[colIdx.usuario] || '').trim() : '';
  const clave = colIdx.clave !== -1 ? String(row[colIdx.clave] || '').trim() : '';
  let sheetDns = colIdx.dns !== -1 ? String(row[colIdx.dns] || '').trim() : '';
  let sheetDnsSmarters = colIdx.dnsSmarters !== -1 ? String(row[colIdx.dnsSmarters] || '').trim() : '';
  const telefono = colIdx.telefono !== -1 ? String(row[colIdx.telefono] || '').trim() : '';

  if (!nombre && !apellido && !usuario) continue;

  let matchedSub = null;

  // Intentar match 1: Usuario exacto / normalizado
  if (usuario) {
    matchedSub = subByUsername.get(usuario.toLowerCase());
  }

  // Intentar match 2: Nombre completo en note
  if (!matchedSub) {
    const fullName = `${nombre} ${apellido}`.replace(/\s+/g, ' ').trim().toLowerCase();
    if (fullName.length > 2) {
      matchedSub = subByNote.get(fullName);
    }
  }

  // Intentar match 3: Teléfono
  if (!matchedSub && telefono) {
    const pDigits = telefono.replace(/\D/g, '');
    if (pDigits.length >= 7) {
      matchedSub = subByPhone.get(pDigits);
    }
  }

  let megaId = '';
  let finalDns = sheetDns;
  let finalDnsSmarters = sheetDnsSmarters;

  if (matchedSub) {
    matchedCount++;
    megaId = String(matchedSub.id || '');
    if (matchedSub.dns_link) {
      finalDns = matchedSub.dns_link;
    } else if (matchedSub.dns) {
      finalDns = matchedSub.dns;
    }

    if (matchedSub.dns_link_for_samsung_lg) {
      finalDnsSmarters = matchedSub.dns_link_for_samsung_lg;
    } else if (matchedSub.dns_smarters) {
      finalDnsSmarters = matchedSub.dns_smarters;
    }
  } else {
    unmatchedCount++;
  }

  outputRows.push([
    nombre,
    apellido,
    usuario,
    clave,
    finalDns,
    finalDnsSmarters,
    megaId
  ]);
}

return [{
  json: {
    sheetExists,
    totalSourceRows: rows.length - 1,
    processedRowsCount: outputRows.length - 1,
    matchedCount,
    unmatchedCount,
    totalSubsFetched: allSubs.length,
    rowsToWrite: outputRows
  }
}];

const proc = $('Procesar Mega y Cruzar con API Mega OTT').first().json;
const writeRes = $input.first().json;

return [{
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    spreadsheet: 'Chatwoot',
    sheet: 'MegaID',
    columns: ['Nombre', 'Apellido', 'Usuario', 'Clave', 'DNS', 'DNS Smarters', 'ID de mega'],
    totalSourceRows: proc.totalSourceRows,
    processedRowsCount: proc.processedRowsCount,
    matchedWithMegaApi: proc.matchedCount,
    unmatchedCount: proc.unmatchedCount,
    megaSubscriptionsFetched: proc.totalSubsFetched,
    sheetCreated: !proc.sheetExists,
    writeDetails: writeRes
  }
}];
